<?php declare(strict_types=1);final class TaskExecutionRepository{public function __construct(private mysqli$db){}public function listOwned(int$task,int$u):array{$s=$this->db->prepare('SELECT e.id_,e.step_id_,e.trace_id,e.attempt_number,e.agent_key,e.model_id,e.status,e.started_at,e.heartbeat_at,e.finished_at,e.error_message,e.created_at FROM TaskExecutions e JOIN Tasks t ON t.id_=e.task_id_ WHERE e.task_id_=? AND t.user_id_=? ORDER BY e.id_');if(!$s)throw new RuntimeException('database_error');$s->bind_param('ii',$task,$u);$s->execute();$o=[];$r=$s->get_result();while($x=$r->fetch_assoc())$o[]=$x;$s->close();return$o;}}
